            return;
        setTimeout(function () {
            chTriggerGOClass();
            tryFinalizeChoiceHandlers();
        }, 150);
        // 兜底轮询: finalize 需要源面板 + Resource<GameObject> 类齐 (探针实证双触发后 ~秒级出现)
